impl Solution{pub fn remove_duplicate_letters(s:String)->String{let b=s.as_bytes();let mut last=[0usize;26];for(i,&c)in b.iter().enumerate(){last[(c-b'a')as usize]=i}let mut used=[false;26];let mut st=vec![];for(i,&c)in b.iter().enumerate(){let k=(c-b'a')as usize;if used[k]{continue}while let Some(&x)=st.last(){if x>c&&last[(x-b'a')as usize]>i{used[(x-b'a')as usize]=false;st.pop();}else{break}}st.push(c);used[k]=true;}String::from_utf8(st).unwrap()}}
